finished, the percpu stats are safely freed.

Fixes: f4676ea74b85 ("net: nexthop: Add nexthop group entry stats")
Cc: stable@vger.kernel.org
Signed-off-by: Mehul Rao <mehulrao@gmail.com>
Reviewed-by: Eric Dumazet <edumazet@google.com>
Reviewed-by: Ido Schimmel <idosch@nvidia.com>
Link: https://patch.msgid.link/20260306233821.196789-1-mehulrao@gmail.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In `remove_nh_grp_entry()`, the new group is published via `rcu_assign_pointer()` and then the removed entry's percpu stats are immediately freed with `free_percpu()`. However, the `synchronize_net()` grace period that ensures all prior RCU readers have finished is only executed later in the caller `remove_nexthop_from_groups()`. This creates a window where an RCU reader that entered before the publish can still see the old group and dereference the freed stats via `nh_grp_entry_stats_inc()`, causing a use-after-free on percpu memory.

Here is the patch:

 static void remove_nh_grp_entry(struct net *net, struct nh_grp_entry *nhge,
-				struct nl_info *nlinfo)
+				struct nl_info *nlinfo,
+				struct list_head *deferred_free)
 {
 	struct nh_grp_entry *nhges, *new_nhges;
 	struct nexthop *nhp = nhge->nh_parent;
 	struct netlink_ext_ack extack;
 	struct nexthop *nh = nhge->nh;
 	struct nh_group *nhg, *newg;
 	int i, j, err;

 	WARN_ON(!nh);

 	nhg = rtnl_dereference(nhp->nh_grp);
 	newg = nhg->spare;

 	/* last entry, keep it visible and remove the parent */
 	if (nhg->num_nh == 1) {
 		remove_nexthop(net, nhp, nlinfo);
 		return;
 	}

 	newg->has_v4 = false;
 	newg->is_multipath = nhg->is_multipath;
 	newg->hash_threshold = nhg->hash_threshold;
 	newg->resilient = nhg->resilient;
 	newg->fdb_nh = nhg->fdb_nh;
 	newg->num_nh = nhg->num_nh;

 	/* copy old entries to new except the one getting removed */
 	nhges = nhg->nh_entries;
 	new_nhges = newg->nh_entries;
 	for (i = 0, j = 0; i < nhg->num_nh; ++i) {
 		struct nh_info *nhi;

 		/* current nexthop getting removed */
 		if (nhg->nh_entries[i].nh == nh) {
 			newg->num_nh--;
 			continue;
 		}

 		nhi = rtnl_dereference(nhges[i].nh->nh_info);
 		if (nhi->family == AF_INET)
 			newg->has_v4 = true;

 		list_del(&nhges[i].nh_list);
 		new_nhges[j].stats = nhges[i].stats;
 		new_nhges[j].nh_parent = nhges[i].nh_parent;
 		new_nhges[j].nh = nhges[i].nh;
 		new_nhges[j].weight = nhges[i].weight;
 		list_add(&new_nhges[j].nh_list, &new_nhges[j].nh->grp_list);
 		j++;
 	}

 	if (newg->hash_threshold)
 		nh_hthr_group_rebalance(newg);
 	else if (newg->resilient)
 		replace_nexthop_grp_res(nhg, newg);

 	rcu_assign_pointer(nhp->nh_grp, newg);

 	list_del(&nhge->nh_list);
-	free_percpu(nhge->stats);
 	nexthop_put(nhge->nh);
+	list_add(&nhge->nh_list, deferred_free);

 	/* Removal of a NH from a resilient group is notified through
 	 * bucket notifications.
 	 */
 	if (newg->hash_threshold) {
 		err = call_nexthop_notifiers(net, NEXTHOP_EVENT_REPLACE, nhp,
 					     &extack);
 		if (err)
 			pr_err("%s\n", extack._msg);
 	}

 	if (nlinfo)
 		nexthop_notify(RTM_NEWNEXTHOP, nhp, nlinfo);
 }

 static void remove_nexthop_from_groups(struct net *net, struct nexthop *nh,
 				       struct nl_info *nlinfo)
 {
 	struct nh_grp_entry *nhge, *tmp;
+	LIST_HEAD(deferred_free);

 	/* If there is nothing to do, let's avoid the costly call to
 	 * synchronize_net()
 	 */
 	if (list_empty(&nh->grp_list))
 		return;

 	list_for_each_entry_safe(nhge, tmp, &nh->grp_list, nh_list)
-		remove_nh_grp_entry(net, nhge, nlinfo);
+		remove_nh_grp_entry(net, nhge, nlinfo, &deferred_free);

 	/* make sure all see the newly published array before releasing rtnl */
 	synchronize_net();
+
+	/* Now safe to free percpu stats — all RCU readers have finished */
+	list_for_each_entry_safe(nhge, tmp, &deferred_free, nh_list) {
+		list_del(&nhge->nh_list);
+		free_percpu(nhge->stats);
+	}
 }



